#include "h743_high_fixture.h"
/* Proposed private API declaration only: the first intended RED is the
 * missing implementation. No high profile is generated by this draft. */
extern "C" nx_stm32h743_start_result_t
nx_stm32h743_pll384_system_start(nx_stm32h743_pll384_state_t* owner,
                                 uint32_t cache_mask, uint32_t limit);
class H743HighSystem : public H743HighReference {
  protected:
    nx_stm32h743_start_result_t StartTimebase(uint32_t limit = 8U) {
        return nx_stm32h743_pll384_system_start(&owner, 0U, limit);
    }
};
TEST_F(H743HighSystem, CpuBusAndTimerDomainsRemainDistinct) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    ASSERT_EQ(NX_SUCCESS, StartTimebase().primary);
    const auto c = nx_h743_high_model_clocks();
    EXPECT_EQ(384000000U, c.cpu_hz);
    EXPECT_EQ(192000000U, c.hclk_hz);
    for (uint32_t pclk : c.pclk_hz)
        EXPECT_EQ(96000000U, pclk);
    EXPECT_EQ(192000000U, c.tim2_hz);
    EXPECT_EQ(192000000U, c.tim3_hz);
    EXPECT_EQ(191U, g_h743_model.timer.PSC);
    EXPECT_EQ(384000000U, g_nx_stm32h743_system.core_hz);
    EXPECT_TRUE(g_nx_stm32h743_system.started);
}
TEST_F(H743HighSystem,
       OneNominalMillisecondOfTimerInputPublishesOneThousandUs) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    ASSERT_EQ(NX_SUCCESS, StartTimebase().primary);
    EXPECT_EQ(0U, nx_stm32h743_system_now(&g_nx_stm32h743_system));
    nx_h743_high_model_advance_hclk(192000U);
    /* A CPU-derived PSC383 would publish500us and must fail this case. This
     * is a register-derived nominal model, not measured wall-clock accuracy. */
    EXPECT_EQ(1000U, nx_stm32h743_system_now(&g_nx_stm32h743_system));
}
TEST_F(H743HighSystem, WrapKeepsTheExistingSinglePendingOverflowContract) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    ASSERT_EQ(NX_SUCCESS, StartTimebase().primary);
    g_h743_model.timer.CNT = UINT32_MAX - 9U;
    nx_h743_high_model_advance_hclk(192U * 20U);
    EXPECT_EQ((UINT64_C(1) << 32U) + 10U,
              nx_stm32h743_system_now(&g_nx_stm32h743_system));
    nx_stm32h743_system_timer_irq(&g_nx_stm32h743_system);
    EXPECT_EQ((UINT64_C(1) << 32U) + 10U,
              nx_stm32h743_system_now(&g_nx_stm32h743_system));
}
TEST_F(H743HighSystem, MissingClockOwnerCannotAdoptAMatchingFrequencyNumber) {
    g_nx_stm32h743_system.core_hz = 384000000U;
    const uint32_t writes = g_h743_model.writes;
    EXPECT_EQ(NX_ERROR_STATE, StartTimebase().primary);
    EXPECT_EQ(writes, g_h743_model.writes);
    EXPECT_FALSE(g_nx_stm32h743_system.started);
}
TEST_F(H743HighSystem, InvalidBudgetAndContextNeverAccessHardware) {
    EXPECT_EQ(NX_ERROR_INVALID, StartTimebase(0U).primary);
    g_h743_model.privileged = false;
    EXPECT_EQ(NX_ERROR_CONTEXT, StartTimebase().primary);
    EXPECT_EQ(0U, g_h743_model.reads);
    EXPECT_EQ(0U, g_h743_model.writes);
    g_h743_model.privileged = true;
}
TEST_F(H743HighSystem, AnExistingTimebaseCannotBeInitializedAgain) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    ASSERT_EQ(NX_SUCCESS, StartTimebase().primary);
    const uint32_t writes = g_h743_model.writes;
    EXPECT_EQ(NX_ERROR_BUSY, StartTimebase().primary);
    EXPECT_EQ(writes, g_h743_model.writes);
}
TEST_F(H743HighSystem, CacheOnCannotInheritQualificationFromAFixedHsiProfile) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    const uint32_t writes = g_h743_model.writes;
    EXPECT_EQ(NX_ERROR_UNSUPPORTED,
              nx_stm32h743_pll384_system_start(
                  &owner, NX_ARCH_CACHE_DATA | NX_ARCH_CACHE_INSTRUCTION, 8U)
                  .primary);
    EXPECT_EQ(writes, g_h743_model.writes);
    EXPECT_EQ(0U, g_h743_model.cache_enable_calls);
    /* Opening a later cache-on high profile requires replacing this boundary
     * with its own actual enable/withdrawal/failed-stop TDD and ARM evidence.
     */
}
TEST_F(H743HighSystem, DetachedOwnerCannotAdoptAnotherClockLease) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    nx_stm32h743_pll384_state_t other{};
    const uint32_t writes = g_h743_model.writes;
    EXPECT_EQ(NX_ERROR_STATE,
              nx_stm32h743_pll384_system_start(&other, 0U, 8U).primary);
    EXPECT_EQ(writes, g_h743_model.writes);
}
TEST_F(H743HighSystem, CpuFrequencyCannotStandInForTheActualBusPrescalers) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    const uint32_t previous = g_h743_model.rcc.D2CFGR;
    g_h743_model.rcc.D2CFGR = 0U;
    const uint32_t writes = g_h743_model.writes;
    EXPECT_EQ(NX_ERROR_STATE, StartTimebase().primary);
    EXPECT_EQ(writes, g_h743_model.writes);
    g_h743_model.rcc.D2CFGR = previous;
}
TEST_F(H743HighSystem, AForeignPllDividerCannotBeHiddenByNominalCore384) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    const uint32_t pll = g_h743_model.rcc.PLLCKSELR;
    g_h743_model.rcc.PLLCKSELR = (pll & ~(uint32_t)RCC_PLLCKSELR_DIVM1) |
                                 (12U << RCC_PLLCKSELR_DIVM1_Pos);
    const uint32_t writes = g_h743_model.writes;
    EXPECT_EQ(NX_ERROR_STATE, StartTimebase().primary);
    EXPECT_EQ(writes, g_h743_model.writes);
    g_h743_model.rcc.PLLCKSELR = pll;
}
TEST_F(H743HighSystem, ForeignTimpreRejectsBeforeTheFirstTimerWrite) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    g_h743_model.rcc.CFGR |= RCC_CFGR_TIMPRE;
    const uint32_t writes = g_h743_model.writes;
    EXPECT_EQ(NX_ERROR_STATE, StartTimebase().primary);
    EXPECT_EQ(writes, g_h743_model.writes);
    g_h743_model.rcc.CFGR &= ~(uint32_t)RCC_CFGR_TIMPRE;
}
TEST_F(H743HighSystem, UnsettledVoltageRejectsWithoutAcquiringTimerOrCache) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    const uint32_t csr = g_h743_model.power.CSR1;
    g_h743_model.power.CSR1 &= ~(uint32_t)PWR_CSR1_ACTVOSRDY;
    const uint32_t writes = g_h743_model.writes;
    EXPECT_EQ(NX_ERROR_STATE, StartTimebase().primary);
    EXPECT_EQ(writes, g_h743_model.writes);
    EXPECT_EQ(0U, g_h743_model.cache_enable_calls);
    g_h743_model.power.CSR1 = csr;
}
TEST_F(H743HighSystem, RequestedAndActualVoltageMustAgreeBeforeTimerAdmission) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    const uint32_t d3 = g_h743_model.power.D3CR;
    g_h743_model.power.D3CR = PWR_D3CR_VOS_1 | PWR_D3CR_VOSRDY;
    const uint32_t writes = g_h743_model.writes;
    EXPECT_EQ(NX_ERROR_STATE, StartTimebase().primary);
    EXPECT_EQ(writes, g_h743_model.writes);
    g_h743_model.power.D3CR = d3;
}
TEST_F(H743HighSystem, WrongSharedFlashTimingRejectsBeforeAnyTimerMutation) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    g_h743_model.flash.ACR = FLASH_ACR_LATENCY_1WS | FLASH_ACR_WRHIGHFREQ_1;
    const uint32_t writes = g_h743_model.writes;
    EXPECT_EQ(NX_ERROR_STATE, StartTimebase().primary);
    EXPECT_EQ(writes, g_h743_model.writes);
    g_h743_model.flash.ACR = FLASH_ACR_LATENCY_2WS | FLASH_ACR_WRHIGHFREQ_1;
}
TEST_F(H743HighSystem, GateHiddenForeignTimerKeepsItsControlsAndClockOwner) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    g_h743_model.hide_timer_when_gated = true;
    g_h743_model.timer.CCER = TIM_CCER_CC1E;
    const uint32_t effects = owner.remaining_effects;
    const auto result = StartTimebase();
    EXPECT_EQ(NX_ERROR_BUSY, result.primary);
    EXPECT_EQ(NX_SUCCESS, result.cleanup);
    EXPECT_EQ(0U, result.remaining_effects);
    EXPECT_EQ(TIM_CCER_CC1E, g_h743_model.timer.CCER);
    EXPECT_EQ(0U, g_h743_model.timer_reset_writes);
    EXPECT_EQ(effects, owner.remaining_effects);
    g_h743_model.timer.CCER = 0U;
}
TEST_F(H743HighSystem, RefusedPrescalerWriteRollsBackTimebaseButNotClockOwner) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    g_h743_model.ignore_write = &g_h743_model.timer.PSC;
    const auto result = StartTimebase();
    EXPECT_EQ(NX_ERROR_IO, result.primary);
    EXPECT_EQ(NX_SUCCESS, result.cleanup);
    EXPECT_EQ(0U, result.remaining_effects);
    EXPECT_FALSE(g_nx_stm32h743_system.started);
    EXPECT_EQ(RCC_CFGR_SWS_PLL1, g_h743_model.rcc.CFGR & RCC_CFGR_SWS);
    EXPECT_NE(0U, owner.remaining_effects);
    g_h743_model.ignore_write = nullptr;
}
TEST_F(H743HighSystem, FailedTimerSourceWithdrawalRetainsClockUntilRetry) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    ASSERT_EQ(NX_SUCCESS, StartTimebase().primary);
    g_h743_model.ignore_write = &g_h743_model.timer.DIER;
    EXPECT_EQ(NX_ERROR_IO,
              nx_stm32h743_system_stop(&g_nx_stm32h743_system, 8U));
    EXPECT_NE(0U, g_nx_stm32h743_system.remaining_effects);
    EXPECT_EQ(NX_ERROR_BUSY, nx_stm32h743_pll384_stop(&owner, 8U));
    EXPECT_EQ(RCC_CFGR_SWS_PLL1, g_h743_model.rcc.CFGR & RCC_CFGR_SWS);
    g_h743_model.ignore_write = nullptr;
    EXPECT_EQ(NX_SUCCESS, nx_stm32h743_system_stop(&g_nx_stm32h743_system, 8U));
    EXPECT_EQ(NX_SUCCESS, nx_stm32h743_pll384_stop(&owner, 8U));
}
TEST_F(H743HighSystem, ActualNvicWithdrawalMustJoinBeforeLoweringTheClock) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    ASSERT_EQ(NX_SUCCESS, StartTimebase().primary);
    g_h743_model.hold_irq_off = true;
    EXPECT_EQ(NX_ERROR_IO,
              nx_stm32h743_system_stop(&g_nx_stm32h743_system, 8U));
    EXPECT_NE(0U, g_nx_stm32h743_system.remaining_effects);
    EXPECT_EQ(NX_ERROR_BUSY, nx_stm32h743_pll384_stop(&owner, 8U));
    g_h743_model.hold_irq_off = false;
    EXPECT_EQ(NX_SUCCESS, nx_stm32h743_system_stop(&g_nx_stm32h743_system, 8U));
}
TEST_F(H743HighSystem, SuccessfulSystemStopRetainsTheHighClockForItsOwner) {
    ASSERT_EQ(NX_SUCCESS, StartClock().primary);
    ASSERT_EQ(NX_SUCCESS, StartTimebase().primary);
    EXPECT_EQ(NX_SUCCESS, nx_stm32h743_system_stop(&g_nx_stm32h743_system, 8U));
    EXPECT_EQ(0U, g_nx_stm32h743_system.remaining_effects);
    EXPECT_FALSE(g_nx_stm32h743_system.started);
    EXPECT_EQ(RCC_CFGR_SWS_PLL1, g_h743_model.rcc.CFGR & RCC_CFGR_SWS);
    EXPECT_EQ(384000000U, g_nx_stm32h743_system.core_hz);
    EXPECT_NE(0U, owner.remaining_effects);
    EXPECT_EQ(NX_SUCCESS, nx_stm32h743_pll384_stop(&owner, 8U));
    EXPECT_EQ(64000000U, g_nx_stm32h743_system.core_hz);
}
